#include <iostream>
#include <vector>

using namespace std;

const int MOD = 998244353;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> P(n + 2);
    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;
        P[x] = y;
    }
    P[0] = n + 1;
    P[n + 1] = 0;
    n += 2;

    vector<vector<int>> r_cnt(n + 1, vector<int>(n + 1, 0));
    for (int i = 0; i < n; ++i) {
        ++r_cnt[i + 1][P[i] + 1];
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= n; ++j) {
            r_cnt[i + 1][j] += r_cnt[i][j];
        }
    }
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j < n; ++j) {
            r_cnt[i][j + 1] += r_cnt[i][j];
        }
    }

    auto rect_sum = [&](const int xl, const int xr, const int yl, const int yr) {
        return r_cnt[xr][yr] - r_cnt[xr][yl] - r_cnt[xl][yr] + r_cnt[xl][yl];
    };

    vector<long long> dp(n, 0);
    dp[0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (P[i] < P[j]) {
                continue;
            }

            bool is_maximal = true;
            for (int k = i + 1; k < j; ++k) {
                if (P[k] > P[i] || P[k] < P[j]) {
                    continue;
                }
                const int a = rect_sum(i, k, P[j], P[k]);
                const int b = rect_sum(k + 1, j, P[k] + 1, P[i]);
                if (a == 0 && b == 0) {
                    is_maximal = false;
                    break;
                }
            }

            if (is_maximal) {
                dp[j] = (dp[j] + dp[i]) % MOD;
            }
        }
    }

    cout << dp[n - 1] << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <numeric>

using namespace std;

const int MOD = 998244353;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;
    string s;
    cin >> s;

    // Delete last 'B'
    size_t last_b = s.rfind('B');
    if (last_b == string::npos) {
        cout << 1 << "\n";
        return 0;
    }
    s = s.substr(0, last_b);

    // Strip trailing 'R's
    while (!s.empty() && s.back() == 'R') {
        s.pop_back();
    }
    if (s.empty() || s.find('B') == string::npos) {
        cout << 1 << "\n";
        return 0;
    }

    // Split by 'B'
    // S = R^{c_B} B R^{c_{B-1}} B ... R^{c_1} B
    vector<int> c_list;
    int current_r = 0;
    for (char ch : s) {
        if (ch == 'R') {
            current_r++;
        } else {
            c_list.push_back(current_r);
            current_r = 0;
        }
    }
    int B = (int)c_list.size();
    vector<int> c(B + 1, 0);
    for (int i = 1; i <= B; ++i) {
        c[i] = c_list[B - i];
    }
    int R = 0;
    for (int i = 1; i <= B; ++i) R += c[i];

    vector<int> suf_c(B + 1, 0);
    for (int m = 1; m <= B; ++m) {
        suf_c[m] = suf_c[m - 1] + c[B - m + 1];
    }

    vector<long long> fact(B + 1, 1), inv(B + 1, 1);
    for (int i = 1; i <= B; ++i) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    inv[B] = modInverse(fact[B]);
    for (int i = B - 1; i >= 0; --i) {
        inv[i] = (inv[i + 1] * (i + 1)) % MOD;
    }

    // dp[m][s]
    vector<vector<int>> dp(B + 1, vector<int>(R + 1, 0));
    // For v = 0, we can take cnt copies of 0:
    for (int cnt = 0; cnt <= B; ++cnt) {
        dp[cnt][0] = inv[cnt];
    }

    for (int v = 1; v <= R; ++v) {
        vector<vector<int>> next_dp = dp;
        for (int cnt = 1; cnt <= B && cnt * v <= R; ++cnt) {
            long long term = inv[cnt];
            int v_sum = cnt * v;
            for (int m = 0; m <= B - cnt; ++m) {
                int max_s = suf_c[m];
                int nm = m + cnt;
                int max_ns = suf_c[nm];
                for (int s = 0; s <= max_s; ++s) {
                    if (!dp[m][s]) continue;
                    int ns = s + v_sum;
                    if (ns <= max_ns) {
                        next_dp[nm][ns] = (next_dp[nm][ns] + dp[m][s] * term) % MOD;
                    }
                }
            }
        }
        dp = move(next_dp);
    }

    long long ans = 0;
    for (int s = 0; s <= suf_c[B]; ++s) {
        ans = (ans + dp[B][s]) % MOD;
    }
    ans = (ans * fact[B]) % MOD;

    cout << ans << "\n";
    return 0;
}

