map<vector<int>, int> rev[M];
vector<int> tmp;

void make_state(int cut, int k, bool pre, int nxt) {
    if (k == m) {
        rev[cut][tmp] = state[cut].size();
        state[cut].push_back(tmp);
        return;
    }
    tmp.push_back(0);
    make_state(cut, k + 1, false, nxt);
    tmp.pop_back();
    if (pre && (k != cut)) {
        tmp.push_back(tmp[k]);
        make_state(cut, k + 1, true, nxt);
        tmp.pop_back();
    } else {
        rep(i, nxt) {
            tmp.push_back(i + 1);
            make_state(cut, k + 1, true, max(nxt, i + 2));
            tmp.pop_back();
        }
    }
}

void renumbering() {
    int sz = tmp.size();
    int c[10], nxt = 1;
    rep(i, 10) c[i] = 0;
    rep(i, sz) {
        if (tmp[i] > 0) {
            if (c[tmp[i]] == 0) {
                c[tmp[i]] = nxt;
                nxt++;
            }
            tmp[i] = c[tmp[i]];
        }
    }
}

int judge(int k) {
    int sz = tmp.size();
    int cnt = 0, mx = 0;
    rep(i, sz) {
        mx = max(mx, tmp[i]);
        if (tmp[i] == tmp[k]) cnt++;
    }
    if (cnt > 1) return 0;
    if (mx > 1) return -1;
    return 1;
}

