                        dp2[to] = min(dp2[to], dp[idx]);
                    }
                    tmp[j + 1] = tmp[j];
                    int to = rev[(j + 1) % m][tmp];
                    dp2[to] = min(dp2[to], dp[idx] + 1);
                } else if (tmp[j] == tmp[j + 1]) {
                    if (s[i][j] == '.') {
                        tmp[j + 1] = 0;
                        int to = rev[(j + 1) % m][tmp];
                        dp2[to] = min(dp2[to], dp[idx]);
                    }
                    tmp = state[j][idx];
                    int to = rev[(j + 1) % m][tmp];
                    dp2[to] = min(dp2[to], dp[idx] + 1);
                } else {
                    if (s[i][j] == '.') {
                        int x = judge(j + 1);
                        if (x == 0) {
                            tmp[j + 1] = 0;
                            renumbering();
                            int to = rev[(j + 1) % m][tmp];
                            dp2[to] = min(dp2[to], dp[idx]);
