using namespace std;

const int MOD = 1000000007;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

long long nCr(long long n, int r) {
    if (r < 0 || r > n) return 0;
    long long num = 1, den = 1;
    for (int i = 0; i < r; ++i) {
        num = (num * ((n - i) % MOD)) % MOD;
        den = (den * (i + 1)) % MOD;
    }
    return num * modInverse(den) % MOD;
}

int calc_lis(const vector<int>& r) {
    vector<int> dp;
    for (int x : r) {
        auto it = lower_bound(dp.begin(), dp.end(), x);
        if (it == dp.end()) dp.push_back(x);
        else *it = x;
    }
    return (int)dp.size();
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    long long total_space = 1;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        total_space = (total_space * a[i]) % MOD;
    }

    // Generate all ordered partitions
    // Recursive generator for set partitions into k parts
    vector<pair<vector<int>, int>> ordered_partitions;

    auto get_partitions = [&](auto& self, vector<int> elements) -> vector<vector<vector<int>>> {
        if (elements.empty()) return {{}};
        int first = elements[0];
        vector<int> rest(elements.begin() + 1, elements.end());
        auto sub = self(self, rest);
        vector<vector<vector<int>>> res;
        for (const auto& p : sub) {
            for (size_t i = 0; i < p.size(); ++i) {
                auto np = p;
                np[i].insert(np[i].begin(), first);
                res.push_back(np);
            }
            auto np = p;
            np.insert(np.begin(), {first});
            res.push_back(np);
        }
        return res;
    };

    vector<int> all_elems(n);
    iota(all_elems.begin(), all_elems.end(), 0);
    auto partitions = get_partitions(get_partitions, all_elems);

    for (auto& p : partitions) {
        int k = (int)p.size();
        vector<int> perm(k);
        iota(perm.begin(), perm.end(), 0);
        do {
            vector<int> r(n);
            for (int rank = 0; rank < k; ++rank) {
                for (int elem : p[perm[rank]]) {
                    r[elem] = rank;
                }
            }
            ordered_partitions.push_back({r, k});
        } while (next_permutation(perm.begin(), perm.end()));
    }

    // Coordinates and intervals
    vector<int> coords = {0};
    for (int x : a) coords.push_back(x);
    sort(coords.begin(), coords.end());
    coords.erase(unique(coords.begin(), coords.end()), coords.end());

    struct Interval {
        int left, right, len;
    };
    vector<Interval> intervals;
    for (size_t i = 0; i + 1 < coords.size(); ++i) {
        intervals.push_back({coords[i] + 1, coords[i + 1], coords[i + 1] - coords[i]});
    }

    int num_intervals = (int)intervals.size();
    vector<vector<long long>> comb(num_intervals, vector<long long>(n + 1, 0));
    for (int m = 0; m < num_intervals; ++m) {
        for (int c = 0; c <= n; ++c) {
            comb[m][c] = nCr(intervals[m].len, c);
        }
    }

    long long total_lis_sum = 0;
    for (const auto& [r, k] : ordered_partitions) {
        int lis_val = calc_lis(r);
        vector<int> U(k, MOD);
        for (int i = 0; i < n; ++i) {
            U[r[i]] = min(U[r[i]], a[i]);
        }

        vector<long long> dp(k + 1, 0);
        dp[0] = 1;

        for (int m = 0; m < num_intervals; ++m) {
            vector<long long> next_dp = dp;
            int right = intervals[m].right;
            for (int j = 0; j < k; ++j) {
                if (!dp[j]) continue;
                for (int c = 1; j + c <= k; ++c) {
                    bool ok = true;
                    for (int t = 0; t < c; ++t) {
                        if (U[j + t] < right) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) {
                        next_dp[j + c] = (next_dp[j + c] + dp[j] * comb[m][c]) % MOD;
                    } else {
                        break;
                    }
                }
            }
            dp = move(next_dp);
        }

        long long ways = dp[k];
        total_lis_sum = (total_lis_sum + ways * lis_val) % MOD;
    }

    long long ans = total_lis_sum * modInverse(total_space) % MOD;
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int max_d = 2 * n * k;
    vector<int> day_mask(max_d + 1, 0);
    for (int i = 0; i < n; ++i) {
        int period = 2 * a[i];
        int work_len = a[i];
        for (int d = 1; d <= max_d; ++d) {
            if ((d - 1) % period < work_len) {
                day_mask[d] |= (1 << i);
            }
        }
    }

    int num_masks = 1 << n;
    vector<int> pop(num_masks, 0);
    for (int mask = 0; mask < num_masks; ++mask) {
        pop[mask] = __builtin_popcount(mask);
    }

    vector<int> sos(num_masks, 0);

    auto check = [&](int D) -> bool {
        fill(sos.begin(), sos.end(), 0);
        for (int d = 1; d <= D; ++d) {
            sos[day_mask[d]]++;
        }

        for (int i = 0; i < n; ++i) {
            int bit = 1 << i;
            for (int mask = 0; mask < num_masks; ++mask) {
                if (mask & bit) {
                    sos[mask] += sos[mask ^ bit];
                }
            }
        }

        for (int mask = 0; mask < num_masks; ++mask) {
            int subset_size = n - pop[mask];
            if (sos[mask] > D - 1LL * subset_size * k) {
                return false;
            }
        }
        return true;
    };

    int low = 1, high = max_d;
    int ans = high;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <algorithm>

using namespace std;

typedef __int128_t int128;

long long floor_sum_AP(long long n, long long a, long long b) {
    if (n <= 0) return 0;
    long long q = n / b;
    long long r = n % b;
    int128 sum_div = (int128)b * q * (q - 1) / 2 + (int128)r * q;
    return (long long)((int128)n * a + sum_div);
}

long long range_sum_F(long long L, long long R, long long a, long long b) {
    if (L >= R) return 0;
    return floor_sum_AP(R, a, b) - floor_sum_AP(L, a, b);
}

long long ceil_div(int128 num, int128 den) {
    // den > 0
    if (num >= 0) {
        return (long long)((num + den - 1) / den);
    } else {
        return (long long)(num / den);
    }
}

void solve() {
    long long n, ax, bx, ay, by;
    if (!(cin >> n >> ax >> bx >> ay >> by)) return;

    if (bx == by) {
        if (ax == ay) cout << n << "\n";
        else cout << 0 << "\n";
        return;
    }

    if (bx > by) {
        swap(ax, ay);
        swap(bx, by);
    }

    int128 den = by - bx;
    int128 prod = (int128)bx * by;
    int128 D = ax - ay;

    long long x_m1 = ceil_div((-1 - D) * prod, den);
    long long x_0  = ceil_div((0 - D) * prod, den);
    long long x_p1 = ceil_div((1 - D) * prod, den);

    long long ans = 0;

    // Interval 1: [x_m1, x_0)
    long long L1 = max(1LL, x_m1);
    long long R1 = min(n + 1, x_0);
    if (L1 < R1) {
        long long cnt = R1 - L1;
        long long sum_F = range_sum_F(L1, R1, ax, bx);
        long long sum_G = range_sum_F(L1, R1, ay, by);
        ans += cnt - sum_G + sum_F;
    }

    // Interval 2: [x_0, x_p1)
    long long L2 = max(1LL, x_0);
    long long R2 = min(n + 1, x_p1);
    if (L2 < R2) {
        long long cnt = R2 - L2;
        long long sum_F = range_sum_F(L2, R2, ax, bx);
        long long sum_G = range_sum_F(L2, R2, ay, by);
        ans += cnt - sum_F + sum_G;
    }

    cout << ans << "\n";
}

