#include <iostream>
#include <vector>

using namespace std;

const int MOD = 998244353;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> cnt(n + 2, vector<int>(n + 2, 0));
    for (int i = 0; i < m; ++i) {
        int l, r;
        cin >> l >> r;
        for (int left = 1; left <= l; ++left) {
            for (int right = r; right <= n; ++right) {
                cnt[left][right]++;
            }
        }
    }

    // dp[i][k]
    vector<vector<long long>> dp(n + 2, vector<long long>(m + 1, 0));
    dp[0][0] = 1;

    for (int i = 0; i <= n; ++i) {
        for (int k = 0; k <= m; ++k) {
            if (!dp[i][k]) continue;
            long long val = dp[i][k];
            for (int j = i + 1; j <= n + 1; ++j) {
                int add_cnt = (i + 1 <= j - 1) ? cnt[i + 1][j - 1] : 0;
                int nk = k + add_cnt;
                if (nk <= m) {
                    long long coeff = (j <= n) ? (MOD - 1) : 1;
                    dp[j][nk] = (dp[j][nk] + val * coeff) % MOD;
                }
            }
        }
    }

    long long ans = 0;
    int total_all = cnt[1][n];
    for (int k = 0; k <= m; ++k) {
        int c = m - k;
        if (c <= 0) continue;
        long long ways = dp[n + 1][k];
        if (k == total_all) {
            ways = (ways - 1 + MOD) % MOD;
        }
        long long term = (MOD - ways) % MOD;
        long long inv_c = modInverse(c);
        long long contrib = term * m % MOD * inv_c % MOD;
        ans = (ans + contrib) % MOD;
    }

    cout << ans << "\n";
    return 0;
}

