    for (int i = 0; i < n - 1; ++i) {
        ll val = items[i].d;
        int u = items[i].id;
        ll s_u = sz[u];
        ll target_d = val - (n - 2 * s_u);

        auto it = d_to_id.find(target_d);
        if (it == d_to_id.end()) {
            cout << -1 << "\n";
            return 0;
        }
        int v = it->second;
        if (v == u) {
            cout << -1 << "\n";
            return 0;
        }
        edges.push_back({u, v});
        sz[v] += s_u;
    }

    int root = items.back().id;
    if (sz[root] != n) {
        cout << -1 << "\n";
        return 0;
    }

    // Verify distance sum from root
    vector<vector<int>> adj(n + 1);
    for (const auto& e : edges) {
