        long long inv2 = modInverse(2);

        long long ans = 0;
        for (int j = k; j <= n; ++j) {
            ans = (ans + current_comb * current_pow2) % MOD;
            // update comb(j, k - 1) = comb(j - 1, k - 1) * j / (j - (k - 1))
            if (j < n) {
                current_comb = current_comb * j % MOD * modInverse(j - k + 1) % MOD;
                current_pow2 = current_pow2 * inv2 % MOD;
            }
        }
        cout << ans << "\n";
        return 0;
    }

    int a = 0;
    int idx = 0;
    while (idx + 1 < k && s.substr(idx, 2) == "()") {
        a++;
        idx += 2;
    }

    int b = 0;
    int bal = 0;
    for (int i = idx; i < k; ++i) {
        if (s[i] == '(') bal++;
        else bal--;
        if (bal == 0) b++;
    }

    int m = n - k;
    int p1 = 2 * a + b + 3;
    long long term1 = 1LL * b * nCr(1LL * (m - 2) + p1 - 1, p1 - 1) % MOD;

    int p2 = 2 * a + b + 2;
    long long term2 = (nCr(1LL * m + p2 - 1, p2 - 1) + 1LL * b * nCr(1LL * (m - 1) + p2 - 1, p2 - 1)) % MOD;

    long long ans = (term1 + term2) % MOD;
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 998244353;
const int G = 3;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

void ntt(vector<long long>& a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        long long wlen = power(G, (MOD - 1) / len);
        if (invert) wlen = modInverse(wlen);
        for (int i = 0; i < n; i += len) {
            long long w = 1;
            for (int j = 0; j < len / 2; j++) {
                long long u = a[i + j];
                long long v = (a[i + j + len / 2] * w) % MOD;
                a[i + j] = (u + v >= MOD ? u + v - MOD : u + v);
                a[i + j + len / 2] = (u - v < 0 ? u - v + MOD : u - v);
                w = (w * wlen) % MOD;
            }
        }
    }
    if (invert) {
        long long n_inv = modInverse(n);
        for (long long& x : a) x = (x * n_inv) % MOD;
    }
}

vector<long long> multiply(vector<long long> const& a, vector<long long> const& b, int max_len) {
    vector<long long> fa(a.begin(), a.end()), fb(b.begin(), b.end());
    int n = 1;
    while (n < (int)(fa.size() + fb.size())) n <<= 1;
    fa.resize(n);
    fb.resize(n);
    ntt(fa, false);
    ntt(fb, false);
    for (int i = 0; i < n; i++) fa[i] = (fa[i] * fb[i]) % MOD;
    ntt(fa, true);
    if ((int)fa.size() > max_len) fa.resize(max_len);
    return fa;
}

vector<long long> poly_inv(const vector<long long>& a, int deg) {
    vector<long long> res = {modInverse(a[0])};
    while ((int)res.size() < deg) {
        int len = res.size() * 2;
        vector<long long> cur_a(len, 0);
        for (int i = 0; i < min((int)a.size(), len); ++i) cur_a[i] = a[i];

        vector<long long> cur_res = res;
        int n = 1;
        while (n < 2 * len) n <<= 1;
        cur_a.resize(n);
        cur_res.resize(n);

        ntt(cur_a, false);
        ntt(cur_res, false);
        for (int i = 0; i < n; i++) {
            long long term = (2 - cur_a[i] * cur_res[i] % MOD + MOD) % MOD;
            cur_res[i] = (cur_res[i] * term) % MOD;
        }
        ntt(cur_res, true);
        cur_res.resize(len);
        res = move(cur_res);
    }
    res.resize(deg);
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> Q(n + 1, 0);
    vector<long long> P(n + 1, 0);

    Q[0] = 1;
    for (int i = 1; i <= n; ++i) {
        long long sign = 1;
        for (int k = 1; i * k <= n; ++k) {
            int m = i * k;
            if (sign == 1) {
                Q[m] = (Q[m] - 1 + MOD) % MOD;
                P[m] = (P[m] + k) % MOD;
            } else {
                Q[m] = (Q[m] + 1) % MOD;
                P[m] = (P[m] - k + MOD) % MOD;
            }
            sign = -sign;
        }
    }

    // inv_Q = 1 / Q mod x^{n+1}
    vector<long long> inv_Q = poly_inv(Q, n + 1);

    // inv_Q2 = inv_Q^2 mod x^{n+1}
    vector<long long> inv_Q2 = multiply(inv_Q, inv_Q, n + 1);

    // h = P * inv_Q2 mod x^{n+1}
    vector<long long> h = multiply(P, inv_Q2, n + 1);

    cout << h[n] << "\n";
    return 0;
}
